insert into public.rotinas (id, nome) values ('padrao', 'Rotina padrão');
insert into public.treinos (id, rotina_id, ordem, nome, apelido, foco, cardio) values
  ('pernas-a', 'padrao', 1, 'Pernas A', 'Pernas A', 'Quadríceps e glúteo', 'Cardio opcional: 10 min de caminhada leve'),
  ('peito-costas-a', 'padrao', 2, 'Peito e Costas A', 'Peito A', 'Peito e costas', 'Depois: 20 min de caminhada inclinada'),
  ('ombros-bracos-a', 'padrao', 3, 'Ombros e Braços A', 'Ombros A', 'Ombros, bíceps e tríceps', 'Depois: 20 min de caminhada inclinada'),
  ('pernas-b', 'padrao', 4, 'Pernas B', 'Pernas B', 'Glúteo e posterior de coxa', 'Cardio opcional: 10 min de caminhada leve'),
  ('peito-costas-b', 'padrao', 5, 'Peito e Costas B', 'Peito B', 'Peito e costas', 'Depois: 20 min de caminhada inclinada'),
  ('ombros-bracos-b', 'padrao', 6, 'Ombros e Braços B', 'Ombros B', 'Ombros, bíceps e tríceps', 'Depois: 20 min de caminhada inclinada');
insert into public.exercicios (id, treino_id, ordem, nome, series, reps_min, reps_max, descanso, descanso_seg, incremento, dica) values
  ('agachamento', 'pernas-a', 1, 'Agachamento livre (ou no Smith)', 3, 6, 10, '2–3 min', 150, 5, 'Antes, 2 séries leves de aquecimento (não anote). Desça até a coxa ficar pelo menos paralela ao chão; joelhos seguem a ponta dos pés; peito aberto.'),
  ('legpress', 'pernas-a', 2, 'Leg press 45°', 3, 10, 12, '2 min', 120, 10, 'Pés no meio da plataforma, na largura dos ombros. Desça até onde a lombar continua colada no encosto.'),
  ('bulgaro', 'pernas-a', 3, 'Agachamento búlgaro com halteres (cada perna)', 3, 8, 12, '90 s', 90, 2, 'Pé de trás apoiado no banco. Tronco levemente inclinado à frente = mais glúteo. Faça todas as reps de uma perna, depois a outra. Anote o peso de cada halter.'),
  ('extensora', 'pernas-a', 4, 'Cadeira extensora', 3, 12, 15, '60–90 s', 75, 5, 'Segure 1 s lá em cima e desça em 2–3 s.'),
  ('flexora-sentada', 'pernas-a', 5, 'Mesa flexora sentada', 3, 10, 12, '60–90 s', 75, 5, 'Controle a volta; não deixe o peso cair.'),
  ('panturrilha-pe', 'pernas-a', 6, 'Panturrilha em pé (máquina ou Smith)', 4, 10, 15, '60 s', 60, 5, 'Pausa de 1–2 s embaixo, bem alongado, e suba até a ponta dos pés.'),
  ('abd-polia', 'pernas-a', 7, 'Abdominal na polia (ajoelhado)', 3, 10, 15, '60 s', 60, 2.5, 'Enrole a coluna levando o peito em direção ao quadril; quem puxa é o abdômen, não os braços.'),
  ('supino-reto', 'peito-costas-a', 1, 'Supino reto com barra', 3, 6, 10, '2–3 min', 150, 2.5, 'Antes, 2 séries leves. Escápulas apertadas para trás e para baixo, pés firmes no chão; a barra desce na linha do mamilo. Peça ajuda nas séries pesadas.'),
  ('puxada', 'peito-costas-a', 2, 'Puxada frontal aberta (pulldown)', 3, 8, 12, '2 min', 120, 5, 'Pense em levar os cotovelos para baixo, barra até o alto do peito. Sem balançar o tronco.'),
  ('supino-incl-halter', 'peito-costas-a', 3, 'Supino inclinado com halteres', 3, 8, 12, '2 min', 120, 2, 'Banco a ~30°. Desça até sentir o peito alongar. Anote o peso de cada halter.'),
  ('remada-curvada', 'peito-costas-a', 4, 'Remada curvada com barra (ou cavalinho)', 3, 8, 10, '2 min', 120, 2.5, 'Tronco a ~45°, coluna reta. Puxe a barra em direção ao umbigo.'),
  ('peck-deck', 'peito-costas-a', 5, 'Crucifixo na máquina (peck deck)', 2, 12, 15, '60–90 s', 75, 5, 'Abra até alongar o peito e feche apertando o peito, sem bater as mãos.'),
  ('remada-baixa', 'peito-costas-a', 6, 'Remada baixa no cabo (triângulo)', 3, 10, 12, '90 s', 90, 5, 'Puxe até o abdômen e junte as escápulas por 1 s. Sem jogar o tronco para trás.'),
  ('desenv-halter', 'ombros-bracos-a', 1, 'Desenvolvimento com halteres sentado', 3, 8, 10, '2 min', 120, 2, 'Antes, 1 série leve. Banco quase reto; desça até os halteres ficarem na altura das orelhas.'),
  ('elev-lateral', 'ombros-bracos-a', 2, 'Elevação lateral com halteres', 4, 12, 15, '60 s', 60, 1, 'Suba até a altura dos ombros, cotovelos levemente dobrados. Carga leve, sem jogar o corpo.'),
  ('face-pull', 'ombros-bracos-a', 3, 'Face pull na polia (corda)', 3, 12, 15, '60 s', 60, 2.5, 'Puxe a corda em direção à testa, abrindo as mãos para os lados. Fortalece a parte de trás do ombro e ajuda a postura de quem passa o dia no computador.'),
  ('rosca-direta', 'ombros-bracos-a', 4, 'Rosca direta com barra W', 3, 8, 12, '90 s', 90, 2, 'Cotovelos colados ao corpo, sem balançar o tronco. Desça em 2–3 s. Pode fazer em bi-set com o tríceps testa.'),
  ('triceps-testa', 'ombros-bracos-a', 5, 'Tríceps testa com barra W', 3, 8, 12, '90 s', 90, 2, 'Cotovelos apontando para o teto; desça a barra até a testa ou um pouco atrás da cabeça.'),
  ('rosca-martelo', 'ombros-bracos-a', 6, 'Rosca martelo com halteres', 3, 10, 12, '60 s', 60, 2, 'Palmas viradas uma para a outra. Trabalha o braquial, músculo embaixo do bíceps que deixa o braço mais grosso. Pode fazer em bi-set com o tríceps corda.'),
  ('triceps-corda', 'ombros-bracos-a', 7, 'Tríceps na polia com corda', 3, 10, 15, '60 s', 60, 2.5, 'Cotovelos parados ao lado do corpo; no fim, abra a corda e estique o braço todo.'),
  ('stiff', 'pernas-b', 1, 'Stiff / terra romeno com barra', 3, 8, 10, '2–3 min', 150, 5, 'Antes, 1–2 séries leves. Joelhos levemente dobrados; empurre o quadril para trás até alongar atrás da coxa. Coluna reta e barra raspando nas pernas.'),
  ('hip-thrust', 'pernas-b', 2, 'Elevação de quadril (hip thrust)', 4, 8, 12, '2 min', 120, 10, 'Costas apoiadas no banco, queixo levemente para baixo. Aperte o glúteo por 1–2 s no topo. Pode ser com barra ou na máquina.'),
  ('legpress-alto', 'pernas-b', 3, 'Leg press 45° com pés altos', 3, 10, 12, '2 min', 120, 10, 'Pés no alto da plataforma e mais afastados: puxa mais glúteo e posterior de coxa.'),
  ('flexora-deitada', 'pernas-b', 4, 'Mesa flexora deitada', 3, 10, 12, '60–90 s', 75, 5, 'Quadril colado no banco; desça devagar.'),
  ('abdutora', 'pernas-b', 5, 'Cadeira abdutora', 3, 12, 15, '60 s', 60, 5, 'Incline o tronco um pouco à frente para pegar mais glúteo.'),
  ('panturrilha-sentado', 'pernas-b', 6, 'Panturrilha sentado', 3, 12, 15, '60 s', 60, 5, 'Pausa embaixo e amplitude total.'),
  ('elev-pernas', 'pernas-b', 7, 'Elevação de pernas (paralela ou deitado)', 3, 10, 15, '60 s', 60, 0, 'Suba as pernas tirando o quadril do apoio; desça devagar, sem balanço. Sem carga: deixe o kg em branco.'),
  ('supino-incl-barra', 'peito-costas-b', 1, 'Supino inclinado com barra (ou Smith)', 3, 6, 10, '2–3 min', 150, 2.5, 'Antes, 2 séries leves. Banco a ~30°; mesma técnica do supino reto.'),
  ('barra-fixa', 'peito-costas-b', 2, 'Barra fixa (ou graviton)', 3, 6, 10, '2 min', 120, 0, 'Se ainda não faz 6 barras, use o graviton e anote no kg o peso de ajuda. Na barra livre, deixe o kg em branco (ou anote o peso extra, se usar cinto).'),
  ('supino-reto-halter', 'peito-costas-b', 3, 'Supino reto com halteres', 3, 8, 12, '2 min', 120, 2, 'Os halteres deixam descer mais que a barra: alongue bem o peito. Anote o peso de cada halter.'),
  ('serrote', 'peito-costas-b', 4, 'Remada unilateral com halter (cada lado)', 3, 8, 12, '90 s', 90, 2, 'Joelho e mão apoiados no banco. Puxe o halter em direção ao quadril, não ao ombro.'),
  ('crossover', 'peito-costas-b', 5, 'Crossover na polia (de cima para baixo)', 2, 12, 15, '60–90 s', 75, 2.5, 'Leve as mãos para a frente e para baixo, cruzando um pouco no final.'),
  ('remada-maquina', 'peito-costas-b', 6, 'Remada na máquina (articulada)', 3, 10, 12, '90 s', 90, 5, 'Peito apoiado; foque em juntar as escápulas no fim do movimento.'),
  ('desenv-maquina', 'ombros-bracos-b', 1, 'Desenvolvimento na máquina', 3, 8, 10, '2 min', 120, 5, 'Antes, 1 série leve. Desça até as mãos ficarem na altura das orelhas.'),
  ('elev-lateral-polia', 'ombros-bracos-b', 2, 'Elevação lateral na polia (cada lado)', 3, 12, 15, '60 s', 60, 2.5, 'Polia baixa, um braço por vez. O cabo mantém tensão no movimento todo.'),
  ('crucifixo-inverso', 'ombros-bracos-b', 3, 'Crucifixo inverso na máquina', 3, 12, 15, '60 s', 60, 5, 'Peck deck de frente para o encosto; leve os braços para trás usando a parte de trás do ombro.'),
  ('mergulho', 'ombros-bracos-b', 4, 'Mergulho nas paralelas (ou graviton)', 3, 6, 12, '2 min', 120, 0, 'Tronco reto = mais tríceps. Se ainda não faz 6, use o graviton e anote no kg o peso de ajuda.'),
  ('rosca-inclinada', 'ombros-bracos-b', 5, 'Rosca inclinada com halteres', 3, 8, 12, '90 s', 90, 2, 'Banco a ~45°, braços pendurados atrás do corpo: alonga o bíceps ao máximo. Pode fazer em bi-set com o tríceps francês.'),
  ('triceps-frances', 'ombros-bracos-b', 6, 'Tríceps francês na polia (corda)', 3, 10, 12, '60–90 s', 75, 2.5, 'De costas para a polia, braços acima da cabeça. Alonga a cabeça longa do tríceps, a parte que mais dá volume ao braço.'),
  ('rosca-scott', 'ombros-bracos-b', 7, 'Rosca Scott (máquina ou barra W)', 3, 10, 12, '60 s', 60, 2.5, 'Desça controlado até quase esticar; sem tranco embaixo.');
